function lnrP_heirSaleFinal(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ НА ПОКУПАТЕЛЯ','<p><b>Цепочка:</b> свидетельство о регистрации транспортного средства ЛНР на умершего → свидетельство о праве на наследство → ДКП наследник–покупатель → регистрация РФ на покупателя.</p><p>Предварительно регистрировать автомобиль на наследника не требуется. По принятой для Навигатора практике наследник лично участвует в оформлении в МРЭО.</p><p>При успешной регистрации выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>💰 Безопасная передача денег</h3><p>Окончательный расчёт целесообразно производить после совместного обращения в МРЭО и проверки возможности непосредственного оформления автомобиля на покупателя.</p><h3>🛑 Если отказали</h3><p>Получите письменное решение с конкретным правовым основанием.</p>')}
function lnrP_heirGiftFinal(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ НА ОДАРЯЕМОГО','<p><b>Цепочка:</b> свидетельство о регистрации транспортного средства ЛНР на умершего → свидетельство о праве на наследство → договор дарения наследник–одаряемый → регистрация РФ на одаряемого.</p><p>Предварительно регистрировать автомобиль на наследника не требуется. По принятой для Навигатора практике наследник лично участвует в МРЭО.</p><p>При успешной регистрации выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>🛑 Если отказали</h3><p>Получите письменное решение с конкретным правовым основанием.</p>')}
function lnrP_heirParticipation(next){q('Готов ли наследник, указанный в свидетельстве о праве на наследство, лично участвовать в оформлении автомобиля в МРЭО?',[['Да, готов',()=>lnrP_heirBuyerCitizen(next)],['Нет, не может или не хочет участвовать',()=>lnrP_five('Наследник не участвует в оформлении. Практический маршрут фактического владельца — регистрация на 5 лет.')],['Наследник умер',()=>other('Новая наследственная цепочка')],['Связь с наследником утрачена',()=>lnrP_five('Связь с наследником утрачена. Практический маршрут фактического владельца — регистрация на 5 лет.')]])}
function lnrP_heirDisposition(){q('Как планируется оформить автомобиль дальше?',[['Зарегистрировать автомобиль на наследника',lnrP_inheritanceOwner],['Продать автомобиль нынешнему владельцу',()=>lnrP_heirParticipation(lnrP_heirSaleFinal)],['Подарить автомобиль нынешнему владельцу',()=>lnrP_heirParticipation(lnrP_heirGiftFinal)],['Другая ситуация / нет подходящего варианта',()=>other('Л-2В.2.2')]])}
function lnrP_inheritancePending(){result('yellow','🟡 НАСЛЕДСТВО ЕЩЁ НЕ ОФОРМЛЕНО','<p>Свидетельство о праве на наследство на автомобиль ещё не получено.</p><h3>⚖️ Возможны два маршрута</h3><p><b>1. Не ждать окончания оформления наследства.</b> Обратиться за регистрацией автомобиля на российский учёт на ограниченный срок 5 лет. При успешной регистрации выдаётся <b>СТС РФ на ограниченный срок 5 лет без права продажи и с запретом на внесение изменений в регистрационные данные, а также государственные регистрационные номерные знаки РФ</b>. После получения свидетельства о праве на наследство можно обратиться в МРЭО для снятия ограничения и регистрации автомобиля на постоянный российский учёт.</p><p><b>2. Дождаться свидетельства о праве на наследство.</b> После его получения обратиться непосредственно за постоянной регистрацией автомобиля на российский учёт на основании наследства, без промежуточной регистрации на 5 лет.</p><h3>📋 Что выбрать</h3><p>Если автомобилем необходимо пользоваться до завершения наследственного оформления, можно использовать первый маршрут. Если временная регистрация не требуется, можно дождаться свидетельства о праве на наследство и сразу перейти к постоянной регистрации.</p><h3>🛑 Если отказали</h3><p>Не ограничивайтесь устным отказом. Подайте документы официально и получите письменное решение МРЭО с конкретным правовым основанием.</p>')}
function lnrP_inheritanceStatus(){q('Оформлено ли наследство на автомобиль?',[['Да, имеется свидетельство о праве на наследство',lnrP_heirDisposition],['Нет, наследство ещё не оформлено',lnrP_inheritancePending]])}
function lnrP_heirs(){q('Известны ли вам наследники умершего собственника и готовы ли они участвовать в оформлении автомобиля?',[['Да, наследники известны и готовы участвовать',lnrP_inheritanceStatus],['Наследники известны, но не хотят участвовать',()=>lnrP_five('Наличие наследников и их нежелание участвовать не создаёт у фактического владельца право собственности. Основание 5-летней регистрации — объяснение о реальных обстоятельствах владения.')],['Наследники неизвестны / связи с ними нет',()=>lnrP_five('Разыскивать наследников как предварительное условие этого маршрута Навигатор не требует. Пятилетняя регистрация не создаёт право собственности.')],['Наследников нет',()=>lnrP_five('Отсутствие наследников само по себе не делает фактического владельца собственником. Вопрос приобретения права собственности решается отдельно.')]])}
