function limpOwner2Final(extra=''){result('yellow','🟡 РЕГИСТРАЦИЯ АВТОМОБИЛЯ НА ВЛАДЕЛЬЦА 2 НА РОССИЙСКИЙ УЧЁТ НА 5 ЛЕТ','<p>Во временном свидетельстве о регистрации ЛНР указан <b>Владелец 1</b>, а автомобилем фактически владеете вы — <b>Владелец 2</b>.</p>'+extra+'<h3>⚖️ Что предусматривает маршрут</h3><p>По принятой в Навигаторе логике Владелец 2 может обратиться за временной регистрацией автомобиля на российский государственный учёт на 5 лет на своё имя. При успешной регистрации выдаются <b>СТС РФ на ограниченный срок 5 лет без права продажи и с запретом на внесение изменений в регистрационные данные, а также государственные регистрационные номерные знаки РФ</b>. Такая регистрация сама по себе не означает признания права собственности на автомобиль.</p><h3>📋 Что делать</h3><p>Подготовьте сохранившееся свидетельство временной регистрации ЛНР либо официальное подтверждение прежней временной регистрации, имеющиеся регистрационные документы на автомобиль и представьте автомобиль на осмотр. Обстоятельства фактического владения указывайте такими, какими они были в действительности.</p><p>ДКП, договор дарения, доверенность или расписка между Владельцем 1 и Владельцем 2 в этой ветке не рассматриваются как основание перехода права собственности на автомобиль.</p><h3>🚘 Как может быть на практике</h3><p>По известной нам практике МРЭО в подобных ситуациях нередко отказывает Владельцу 2 из-за того, что прежняя временная регистрация оформлена на другое лицо. Практический отказ не приравниваем к отсутствию самого маршрута: документы следует подать официально и потребовать письменное решение.</p><h3>📖 Подробнее о регистрации на Владельца 2</h3><p><a href="https://rk-avtopravo.ru/registraciya-avto-na-vladelca-2-sts-dnr-lnr/" target="_blank" rel="noopener">Регистрация автомобиля на Владельца 2 со свидетельством ДНР/ЛНР</a></p>'+limpMainArticle()+'<h3>🛑 Если отказали</h3><p>Не ограничивайтесь устным отказом. Получите письменное решение МРЭО с конкретным правовым основанием, проанализируйте его и при наличии оснований обжалуйте административно либо в суде.</p><h3>⚠️ Приобретательная давность</h3><p>Навигатор пока не присоединяет автоматически период владения Владельца 1 к периоду Владельца 2 для вывода о приобретательной давности. Этот вопрос требует отдельной правовой оценки.</p>')}
function limpOwner2Docs(){q('Сохранился ли документ, подтверждающий временную регистрацию автомобиля в ЛНР на Владельца 1?',[['Да, временное свидетельство ЛНР сохранилось',limpOwner2Final],['Свидетельство было изъято, но имеется справка или письменное подтверждение МРЭО',limpOwner2Final],['Документ утрачен или изъят, подтверждения нет, но с Владельцем 1 можно связаться',()=>result('yellow','🟡 НУЖНО ПОДТВЕРДИТЬ ПРЕЖНЮЮ РЕГИСТРАЦИЮ','<p>Получить официальное подтверждение прежней временной регистрации может <b>Владелец 1</b> — лицо, на которое была оформлена временная регистрация ЛНР.</p><p>После подтверждения регистрации можно продолжить маршрут регистрации автомобиля на Владельца 2 на российский учёт на 5 лет.</p>'+limpArticle()+'<h3>🛑 Если МРЭО отказывает Владельцу 1</h3><p>Нужно получить письменный ответ с конкретным основанием отказа и оценить его обжалование.</p>')],['Документов или подтверждения нет и связаться с Владельцем 1 невозможно',limpOwner2UkraineDocs],['Владелец 1 умер',limpDeadHolder],['Другая ситуация / нет подходящего варианта',()=>other('Л-ИМП.2Б.1')]],'<p>В этой ветке не используем ДКП, договор дарения, доверенность или расписку между Владельцем 1 и Владельцем 2 как основание перехода права собственности.</p>')}
function limpOwner2UkraineDocs(){q('Сохранились ли украинские регистрационные документы на автомобиль?',[['Да, сохранились',()=>limpOwner2Final('<p><b>Дополнительное обстоятельство:</b> украинские регистрационные документы сохранились и могут дополнительно подтверждать историю автомобиля.</p>')],['Нет, украинских регистрационных документов нет',()=>limpOwner2Final('<p><b>Дополнительное обстоятельство:</b> украинские регистрационные документы отсутствуют. Это само по себе не исключает пятилетний маршрут, но может усложнить доказывание истории автомобиля и увеличить риск отказа МРЭО.</p>')],['Другая ситуация / нет подходящего варианта',()=>other('Л-ИМП.2Б.2')]],'<p>ℹ️ Украинские регистрационные документы могут упростить подтверждение истории автомобиля. Их отсутствие само по себе не означает невозможность регистрации на российский учёт на 5 лет.</p>')}
function limpHolder(){q('На кого была оформлена временная регистрация автомобиля в ЛНР?',[['На меня — я Владелец 1',limpFirstDate],['На другого человека — я Владелец 2',limpOwner2Docs],['Владелец 1 умер',limpDeadHolder],['Другая ситуация / нет подходящего варианта',()=>other('Л-ИМП.2')]],'<p>Смотрите свидетельство о временной регистрации ЛНР либо официальный документ МРЭО, подтверждающий такую регистрацию.</p>')}
function limpConfirm(){q('Имеется ли документ, подтверждающий прежнюю временную регистрацию автомобиля в ЛНР?',[['Да, имеется справка или письменный ответ МРЭО',limpHolder],['Нет, письменно в МРЭО ещё не обращался',()=>result('yellow','🟡 СНАЧАЛА ПОДТВЕРДИТЕ ПРЕЖНЮЮ РЕГИСТРАЦИЮ','<p>Обратитесь в МРЭО письменно за сведениями о прежней временной регистрации автомобиля в ЛНР.</p>'+limpArticle()+'<h3>🛑 Если отказали</h3><p>Получите письменный ответ с основанием отказа. После этого можно определить дальнейший способ защиты.</p>')],['Обращался письменно, но МРЭО отказало',()=>result('yellow','🟡 ПОЛУЧЕН ОТКАЗ МРЭО','<p>Письменный отказ необходимо анализировать по указанному в нём правовому основанию и при наличии оснований обжаловать.</p>'+limpArticle()+'<h3>🛑 Что делать</h3><p>Сохраните заявление и письменный ответ МРЭО. Не ограничивайтесь устными пояснениями сотрудников.</p>')],['В МРЭО сообщили, что сведений о регистрации нет / база отсутствует',()=>result('yellow','🟡 ТРЕБУЕТСЯ ДОПОЛНИТЕЛЬНОЕ ДОКАЗЫВАНИЕ','<p>Отсутствие сведений в имеющейся базе само по себе не используется Навигатором как автоматический вывод о том, что временной регистрации ЛНР не было.</p>'+limpArticle()+'<h3>🛑 Что делать</h3><p>Получите официальный письменный ответ МРЭО и определите дальнейший доказательственный маршрут.</p>')],['Другая ситуация / нет подходящего варианта',()=>other('Л-ИМП.1.1')]])}
function limpDocs(){q('Изымались ли в МРЭО документы временной регистрации ЛНР?',[['Нет, документы временной регистрации ЛНР сохранились',limpHolder],['Да, документы были изъяты в МРЭО',limpConfirm],['Другая ситуация / нет подходящего варианта',()=>other('Л-ИМП.1')]],'<p>ℹ️ Речь именно о <b>свидетельстве временной регистрации ЛНР</b>. Наличие регистрационных знаков ЛНР само по себе в этой ветке не рассматривается как достаточное подтверждение прежней регистрации.</p>')}

function lnrD1(){q('Какая регистрация указана в документах ЛНР?',[['Постоянная регистрация ЛНР',lnrOwner],['Временная регистрация ЛНР на 5 лет (автомобиль не ввозился из-за рубежа до вхождения ЛНР в состав РФ)',tempLnr],['Временная регистрация ЛНР автомобиля, ввезённого из-за рубежа до вхождения ЛНР в состав РФ',limpDocs],['Другая ситуация / нет подходящего варианта',()=>other('Л-1')]])}

function ukrOwnResidenceEntry(){q('Можно ли подтвердить выезд с территории нового региона и въезд на территорию Российской Федерации?',[['Да — имеются сведения или документы о пересечении границы, которые могут подтверждаться данными ФТС России',()=>pending('Украина: фактическое проживание подтверждено; имеются сведения о последующем въезде в Российскую Федерацию')],['Да — прямых данных о пересечении границы нет, но имеются документы о последующем систематическом проживании на территории РФ',()=>pending('Украина: фактическое проживание подтверждено; въезд подтверждается совокупностью последующих юридически значимых фактов проживания в Российской Федерации')],['Имеются и сведения о пересечении границы, и документы о последующем проживании в РФ',()=>pending('Украина: имеются сведения о въезде и последующем проживании в Российской Федерации')],['Нет',()=>pending('Украина: требуется индивидуальный анализ доказательств въезда и последующего проживания в Российской Федерации')]],'<p>ℹ️ При отсутствии регистрации по месту жительства эта ветка оценивает не только документы о фактическом проживании в административных границах нового региона, но и сведения о последующем въезде в Российскую Федерацию и проживании после въезда.</p>')}
function ukrOwnResidenceEvidence(){q('Можно ли документально подтвердить фактическое проживание на территории нового региона на 30 сентября 2022 года?',[['Да',ukrOwnResidenceEntry],['Нет',()=>pending('Украина: регистрация по месту жительства отсутствовала, документальное подтверждение фактического проживания требует дополнительного анализа')]],'<p>ℹ️ Если регистрации по месту жительства на территории нового региона не было, необходимо подтвердить фактическое проживание в административных границах нового региона документами. Далее Навигатор отдельно проверит сведения о выезде и последующем проживании на территории Российской Федерации.</p>')}
function ukrOwnProofType(){q('Какие документы подтверждают, что на 30 сентября 2022 года вы проживали или были зарегистрированы по месту жительства на территории нового региона?',[['Есть документ о регистрации по месту жительства на территории нового региона',()=>pending('Украина: имеется документ о регистрации по месту жительства на территории нового региона')],['Регистрации по месту жительства не было, но есть другие документы, подтверждающие фактическое проживание',ukrOwnResidenceEvidence],['Есть и регистрация по месту жительства, и другие подтверждающие документы',()=>pending('Украина: имеются регистрация по месту жительства и другие подтверждения фактического проживания')],['Другая ситуация / нет подходящего варианта',()=>other('У-2А.4')]])}
function ukrOwnProof(){q('Имеются ли у вас документы, подтверждающие, что на 30 сентября 2022 года вы проживали или были зарегистрированы по месту жительства на территории нового региона?',[['Да, имеются',ukrOwnProofType],['Нет',()=>pending('Украина: фактическое проживание или регистрация заявлены, но подтверждающих документов сейчас нет')]],'<p>ℹ️ Отсутствие документа на этом этапе не означает автоматический отказ. Дальше Навигатор будет учитывать возможность подтверждения фактического проживания другими допустимыми доказательствами.</p>')}
function ukrOwnRegion(){q('На 30 сентября 2022 года вы проживали или были зарегистрированы по месту жительства на территории одного из новых регионов?',[['Да — на территории нового региона, находившейся под контролем Российской Федерации',ukrOwnProof],['Да — на территории нового региона, которая впоследствии была освобождена',ukrOwnProof],['Да — на территории нового региона, которая находится под контролем Украины',ukrOwnProof],['Нет — на 30 сентября 2022 года не проживал и не был зарегистрирован по месту жительства на территории нового региона',()=>pending('Украина: отсутствует проживание или регистрация по месту жительства в новом регионе на 30 сентября 2022 года')]],'<p>ℹ️ Для целей Навигатора под новыми регионами понимаются ДНР, ЛНР, Запорожская и Херсонская области.</p><p><b>Важно:</b> для целей этой ветки освобождённая территория нового региона и территория нового региона, находящаяся под контролем Украины, рассматриваются одинаково. Сам по себе фактический контроль над территорией не исключает её из рассматриваемого юридического маршрута.</p>')}
function ukrOwnCitizen(){q('Являетесь ли вы гражданином Российской Федерации?',[['Да',ukrOwnRegion],['Нет',()=>pending('Украина: заявитель не является гражданином РФ — требуется определить применимый порядок регистрации')]])}
function ukrOwnDate(){q('Когда автомобиль был зарегистрирован на Украине на ваше имя?',[['Не позднее 31 декабря 2025 года',ukrOwnCitizen],['После 31 декабря 2025 года',()=>result('red','🔴 РЕГИСТРАЦИЯ ПО СПЕЦИАЛЬНОМУ ПОРЯДКУ НЕ ПРЕДУСМОТРЕНА','<p><b>По выбранным ответам автомобиль зарегистрирован на Украине после 31 декабря 2025 года.</b></p><h3>⚖️ Что предусматривает специальный порядок</h3><p>Рассматриваемый порядок распространяется на транспортные средства, зарегистрированные на территории Украины не позднее 31 декабря 2025 года. Если регистрация автомобиля произведена позже этой даты, данный специальный порядок регистрации на российский учёт на автомобиль не распространяется.</p><h3>📋 Что это означает</h3><p>Навигатор не продолжает эту ветку по специальному порядку. Необходимо отдельно определять, существует ли иной законный порядок оформления конкретного автомобиля.</p><h3>🛑 Если в МРЭО возник спор</h3><p>Устный отказ не является окончательным решением. При необходимости подайте обращение официально и получите письменное решение с указанием правового основания.</p>')]],'<p>ℹ️ Для этой ветки имеет значение предельная дата регистрации автомобиля на Украине — <b>31 декабря 2025 года</b>.</p>')}
function ukrIntro(){hist.push(ukrIntro);app.innerHTML='<section class="q">'+badge('INFO-УКРАИНА')+'<h2>🇺🇦 Автомобиль с украинской регистрацией: сначала важно понять одну особенность</h2><p>На территориях новых регионов возникают ситуации с автомобилями, которые обычное законодательство изначально не предусматривало.</p><p>Автомобиль мог остаться на освобождаемой территории, быть зарегистрирован на Украине, перейти к другому владельцу, находиться без части документов или попасть на территорию Российской Федерации спустя несколько лет после сделки. Документы могли быть утрачены, архивы — недоступны, а выполнить отдельные формальные требования иногда объективно невозможно.</p><p>Специальные нормы помогают включать транспорт жителей новых регионов в российское правовое поле, но не всегда охватывают всё многообразие реальных ситуаций. Поэтому конкретный автомобиль может <b>не укладываться в стандартную административную процедуру регистрации в МРЭО</b>. Это ещё не означает, что у владельца отсутствуют права на автомобиль или что вопрос невозможно решить.</p><h3>⚖️ Иногда административной процедуры недостаточно</h3><p>Некоторые проблемы относятся уже не только к регистрации, но и к <b>праву собственности на автомобиль</b>. Может потребоваться установить юридически значимые обстоятельства, подтвердить сделку, наследование, длительное владение либо признать право собственности.</p><p>Тогда вопрос может перейти из административной плоскости в <b>гражданско-правовую</b>, а право на автомобиль — устанавливаться или защищаться в судебном порядке. Поэтому ответ сотрудника МРЭО <b>«зарегистрировать невозможно» не всегда означает, что законных вариантов больше нет</b>.</p><h3>🛑 Если в МРЭО или таможенном органе отказали</h3><p>Особенно осторожно относитесь к <b>устному отказу</b>. Фразы «не положено», «система не пропускает» или «такие автомобили не ставим» сами по себе не заменяют письменного решения по вашей ситуации.</p><ol><li><b>Не ограничивайтесь устным ответом.</b> Подайте документы официально и получите письменное решение с указанием правовых оснований отказа.</li><li><b>Не считайте ситуацию безвыходной до анализа причин отказа.</b></li><li><b>Покажите письменный отказ автоюристу.</b> Его нужно сопоставить с документами и фактическими обстоятельствами.</li><li>При наличии законных оснований <b>решение можно обжаловать</b>. Если спор касается непосредственно права на автомобиль, может потребоваться обращение в суд.</li></ol><h3>🚗 Для чего нужен этот Навигатор</h3><p>Навигатор последовательно разберёт: <b>откуда прибыл автомобиль → на каком учёте он находится → на кого оформлены документы → когда и при каких обстоятельствах возникло владение → какие документы сохранились → какой административный или гражданско-правовой путь может подойти.</b></p><p class="warn"><b>Важно:</b> если готового сценария нет, это <b>не означает невозможность оформления</b>. Ситуация может требовать индивидуального правового анализа.</p><div class="opts"><button id="ukr-go">Продолжить проверку автомобиля →</button></div><button class="back" id="back">← Назад</button></section>';document.getElementById('ukr-go').onclick=ukrOwner;document.getElementById('back').onclick=()=>{hist.pop();let f=hist.pop();f&&f()}}
function ukrOtherOwnerFiveResult(){result('green','🟢 РЕГИСТРАЦИЯ РФ НА ОГРАНИЧЕННЫЙ СРОК 5 ЛЕТ','<p><b>По выбранным ответам автомобиль подпадает под рассматриваемый маршрут регистрации транспортного средства, находящегося во владении гражданина.</b></p><h3>⚖️ Что предусматривает закон</h3><p>По подпункту «д» проекта постановления транспортное средство регистрируется без выдачи паспорта транспортного средства на бумажном носителе с выдачей регистрационных документов на ограниченный срок 5 лет.</p><p><b>Выдаётся СТС РФ на ограниченный срок 5 лет без права продажи и с запретом на внесение изменений в регистрационные данные, а также государственные регистрационные номерные знаки РФ.</b></p><p>ПТС на бумажном носителе не выдаётся.</p><h3>🚘 Как может быть на практике</h3><p>Необходимо представить имеющиеся документы и последовательно подтвердить обстоятельства владения автомобилем и территориальное условие. Если дополнительного документа о владении нет либо он оформлен после даты выдачи паспорта РФ, в заявлении указываются реальные обстоятельства приобретения транспортного средства или владения им.</p><h3>📋 Что делать</h3><p>Подготовить документ, удостоверяющий личность, свидетельство о регистрации транспортного средства Украины, имеющийся документ о владении — доверенность, договор лизинга либо иной договор — если он имеется, а также документы, подтверждающие соответствие территориальному условию. Обратиться в регистрационное подразделение для проведения регистрационного действия.</p><h3>🛑 Что делать, если отказали</h3><p>Устный отказ не является окончательным результатом. Подайте документы официально и потребуйте письменное решение с конкретным правовым основанием отказа. После этого можно проверить законность указанного основания и определить порядок обжалования.</p><h3>📚 Нормативное основание</h3><p>Подпункт «д» проекта постановления о специальном порядке регистрации транспортных средств в новых регионах. После официального принятия постановления номер, дата и окончательная редакция нормы должны быть проверены и обновлены в Навигаторе.</p>')}
function ukrOtherOwnerTerritory(){q('На 30 сентября 2022 года вы постоянно проживали на территории одного из новых регионов либо ранее постоянно проживали там и затем выехали в другой субъект Российской Федерации?',[['Да — постоянно проживал на территории нового региона на 30 сентября 2022 года',ukrOtherOwnerFiveResult],['Да — ранее постоянно проживал на территории нового региона и затем выехал в другой субъект Российской Федерации',ukrOtherOwnerFiveResult],['Нет',()=>pending('Украина: территориальное условие подпункта «д» для пятилетней регистрации владельца не подтверждено')]],'<p>ℹ️ Нынешнее проживание в другом регионе России само по себе не исключает этот маршрут. Для пятилетней регистрации по рассматриваемому основанию важно соответствовать территориальному условию проекта постановления.</p>')}
function ukrOtherOwnerStatement(){q('Можете ли вы указать в заявлении обстоятельства приобретения транспортного средства или владения им?',[['Да',ukrOtherOwnerTerritory],['Нет',()=>pending('Украина: для маршрута владельца необходимо указать обстоятельства приобретения транспортного средства или владения им')]],'<p>ℹ️ В этой ситуации маршрут строится на сведениях владельца, указанных в заявлении об обстоятельствах приобретения транспортного средства (владения транспортным средством). При выполнении остальных условий эта ветка ведёт к регистрации на ограниченный срок 5 лет.</p>')}
function ukrOtherOwnerNoDoc(){ukrOtherOwnerStatement()}
function ukrOtherOwnerDocDate(doc){q('Когда был оформлен документ, на основании которого автомобиль находится в вашем владении?',[['До даты выдачи мне паспорта гражданина Российской Федерации и не позднее 31 декабря 2025 года',ukrOtherOwnerTerritory],['После даты выдачи мне паспорта гражданина Российской Федерации',ukrOtherOwnerStatement]],'<p>ℹ️ Наличие документа, соответствующего указанному сроку, является способом подтверждения владения, но <b>не изменяет регистрационный режим</b>: при выполнении остальных условий эта ветка ведёт к регистрации на ограниченный срок 5 лет.</p><p>Если документ оформлен после даты выдачи паспорта РФ, для этой ветки используются сведения владельца в заявлении об обстоятельствах приобретения транспортного средства (владения транспортным средством).</p>')}
function ukrDeceasedHeirBuyerFinal(){result('green','🟢 РЕГИСТРАЦИЯ АВТОМОБИЛЯ НА ПРИОБРЕТАТЕЛЯ НА РОССИЙСКИЙ УЧЁТ','<h3>⚖️ Что предусматривает специальный порядок</h3><p>Автомобиль был зарегистрирован на Украине не позднее <b>31 декабря 2025 года</b>. Право на автомобиль после смерти зарегистрированного собственника подтверждено <b>свидетельством о праве на наследство</b>, а наследник передаёт автомобиль приобретателю по <b>договору купли-продажи или договору дарения</b>. Приобретатель соответствует территориальному условию специального порядка.</p><h3>📋 Что подготовить</h3><ul><li>свидетельство о регистрации транспортного средства Украины;</li><li>свидетельство о праве на наследство;</li><li>договор купли-продажи или договор дарения между наследником и приобретателем;</li><li><b>паспорт гражданина РФ наследника (продавца/дарителя);</b></li><li>паспорт гражданина РФ приобретателя;</li><li>документы, подтверждающие постоянное проживание приобретателя на территории нового региона на соответствующую дату;</li><li>автомобиль для осмотра.</li></ul><p>При успешной регистрации приобретателю выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>🚘 Как может быть на практике</h3><p>Поскольку в украинском свидетельстве указан умерший собственник, необходимо показать МРЭО непрерывную юридическую цепочку перехода права:</p><p><b>умерший собственник → свидетельство о праве на наследство → наследник → ДКП/дарение → приобретатель.</b></p><h3>🛑 Если МРЭО отказывает</h3><p>Не ограничивайтесь устным отказом. Представьте документы официально и получите письменное решение с конкретным правовым основанием отказа. После этого можно оценить законность отказа и способ его обжалования.</p>')}
function ukrDeceasedHeirBuyerEvidence(){q('Можно ли документально подтвердить фактическое проживание на территории нового региона на 30 сентября 2022 года?',[['Да',ukrDeceasedHeirBuyerEntry],['Нет',()=>pending('Украина: приобретатель по сделке с наследником заявляет фактическое проживание, но документальное подтверждение требует дополнительного анализа')]],'<p>ℹ️ Если регистрации по месту жительства не было, фактическое проживание в административных границах нового региона необходимо подтвердить документами.</p>')}
function ukrDeceasedHeirBuyerEntry(){q('Можно ли подтвердить выезд с территории нового региона и въезд на территорию Российской Федерации?',[['Да — имеются сведения или документы о пересечении границы, которые могут подтверждаться данными ФТС России',ukrDeceasedHeirBuyerFinal],['Да — прямых данных о пересечении границы нет, но имеются документы о последующем систематическом проживании на территории РФ',ukrDeceasedHeirBuyerFinal],['Имеются и сведения о пересечении границы, и документы о последующем проживании в РФ',ukrDeceasedHeirBuyerFinal],['Нет',()=>pending('Украина: требуется индивидуальный анализ доказательств выезда, въезда и последующего проживания приобретателя')]],'<p>ℹ️ При отсутствии регистрации по месту жительства Навигатор учитывает документы о фактическом проживании в новом регионе и сведения о последующем въезде и проживании в Российской Федерации.</p>')}
function ukrDeceasedHeirBuyerProofType(){q('Какие документы подтверждают, что на 30 сентября 2022 года вы проживали или были зарегистрированы по месту жительства на территории нового региона?',[['Есть документ о регистрации по месту жительства на территории нового региона',ukrDeceasedHeirBuyerFinal],['Регистрации по месту жительства не было, но есть другие документы, подтверждающие фактическое проживание',ukrDeceasedHeirBuyerEvidence],['Есть и регистрация по месту жительства, и другие подтверждающие документы',ukrDeceasedHeirBuyerFinal],['Другая ситуация / нет подходящего варианта',()=>other('У-3.5')]])}
function ukrDeceasedHeirBuyerProof(){q('Имеются ли у вас документы, подтверждающие, что на 30 сентября 2022 года вы проживали или были зарегистрированы по месту жительства на территории нового региона?',[['Да, имеются',ukrDeceasedHeirBuyerProofType],['Нет',()=>pending('Украина: территориальная связь приобретателя заявлена, но подтверждающих документов сейчас нет — требуется решить вопрос доказывания')]],'<p>ℹ️ Отсутствие подтверждающего документа на этом этапе не означает автоматический отказ. Требуется определить, какими допустимыми доказательствами можно подтвердить территориальное условие.</p>')}
function ukrDeceasedHeirBuyerTerritory(){q('На 30 сентября 2022 года вы проживали или были зарегистрированы по месту жительства на территории одного из новых регионов?',[['Да — проживал на территории нового региона',ukrDeceasedHeirBuyerProof],['Да — был зарегистрирован по месту жительства на территории нового региона',ukrDeceasedHeirBuyerProof],['Да — проживал и был зарегистрирован по месту жительства',ukrDeceasedHeirBuyerProof],['Нет — не проживал и не был зарегистрирован по месту жительства',()=>result('red','🔴 СПЕЦИАЛЬНЫЙ ПОРЯДОК ДЛЯ ПРИОБРЕТАТЕЛЯ НЕ ПРИМЕНЯЕТСЯ','<p>По выбранным ответам приобретатель автомобиля по договору купли-продажи или дарения на 30 сентября 2022 года не проживал и не был зарегистрирован по месту жительства на территории нового региона.</p><p>Регистрация автомобиля на этого приобретателя по рассматриваемому специальному порядку не предусмотрена.</p>')]],'<p>ℹ️ Для этой ветки учитывается территориальная связь именно приобретателя автомобиля. Нынешнее место проживания само по себе не определяет результат.</p>')}
function ukrDeceasedHeirTransferBasis(){q('Как планируется оформить переход права собственности на автомобиль от наследника к вам?',[['Договор купли-продажи',ukrDeceasedHeirBuyerTerritory],['Договор дарения',ukrDeceasedHeirBuyerTerritory],['Другое основание',()=>pending('Украина: другое основание перехода права собственности от наследника к пользователю — требуется определить его юридическое значение')],['Другая ситуация / нет подходящего варианта',()=>other('У-3.3')]])}
function ukrDeceasedHeirGoal(){q('Что планируется сделать с автомобилем?',[['Зарегистрировать автомобиль на наследника',()=>pending('Украина: наследник со свидетельством о праве на наследство лично участвует в МРЭО и планирует зарегистрировать автомобиль на себя')],['Оформить автомобиль на меня с участием наследника',ukrDeceasedHeirTransferBasis]])}
function ukrDeceasedHeirPresence(){q('Может ли наследник, указанный в свидетельстве о праве на наследство, лично присутствовать в МРЭО при регистрации автомобиля?',[['Да, может присутствовать',ukrDeceasedHeirGoal],['Нет, присутствовать не может',()=>pending('Украина: свидетельство о праве на наследство выдано другому наследнику, требуется определить законный маршрут без его личного присутствия')]])}
function ukrDeceasedPossession(){q('Автомобиль фактически находится в вашем владении и пользовании?',[['Да',ukrDeceasedPossessionBasis],['Нет',()=>pending('Украина: автомобиль умершего собственника не находится во владении заявителя — пятилетний маршрут фактического владельца по этой ветке не формируется')]])}
function ukrDeceasedPossessionBasis(){q('На каком основании автомобиль находится в вашем владении?',[['Доверенность',()=>ukrDeceasedPossessionDocDate('доверенность')],['Договор лизинга',()=>ukrDeceasedPossessionDocDate('договор лизинга')],['Иной договор',()=>ukrDeceasedPossessionDocDate('иной договор')],['Дополнительного документа о владении нет',ukrDeceasedPossessionStatement],['Другая ситуация / нет подходящего варианта',()=>other('У-3.2')]],'<p>ℹ️ Для пятилетнего маршрута проверяется основание владения автомобилем. При отсутствии дополнительного документа используются сведения владельца в заявлении об обстоятельствах приобретения транспортного средства (владения транспортным средством).</p>')}
function ukrDeceasedPossessionDocDate(doc){q('Когда был оформлен документ, на основании которого автомобиль находится в вашем владении?',[['До даты выдачи мне паспорта гражданина Российской Федерации и не позднее 31 декабря 2025 года',ukrDeceasedPossessionTerritory],['После даты выдачи мне паспорта гражданина Российской Федерации',ukrDeceasedPossessionStatement]],'<p>ℹ️ Наличие документа, соответствующего указанному сроку, подтверждает владение, но не изменяет регистрационный режим: при выполнении остальных условий маршрут ведёт к регистрации на ограниченный срок 5 лет.</p><p>Если документ оформлен после даты выдачи паспорта РФ, используются сведения владельца в заявлении об обстоятельствах приобретения транспортного средства (владения транспортным средством).</p>')}
function ukrDeceasedPossessionStatement(){q('Можете ли вы указать в заявлении обстоятельства приобретения транспортного средства или владения им?',[['Да',ukrDeceasedPossessionTerritory],['Нет',()=>pending('Украина: для пятилетнего маршрута владельца необходимо указать обстоятельства приобретения транспортного средства или владения им')]],'<p>ℹ️ При отсутствии подходящего дополнительного документа маршрут строится на сведениях владельца, указанных в заявлении об обстоятельствах приобретения транспортного средства (владения транспортным средством).</p>')}
function ukrDeceasedPossessionTerritory(){q('На 30 сентября 2022 года вы постоянно проживали на территории одного из новых регионов либо ранее постоянно проживали там и затем выехали в другой субъект Российской Федерации?',[['Да — постоянно проживал на территории нового региона на 30 сентября 2022 года',ukrOtherOwnerFiveResult],['Да — ранее постоянно проживал на территории нового региона и затем выехал в другой субъект Российской Федерации',ukrOtherOwnerFiveResult],['Нет',()=>pending('Украина: территориальное условие для пятилетней регистрации фактического владельца не подтверждено')]],'<p>ℹ️ Нынешнее проживание в другом регионе России само по себе не исключает этот маршрут. Проверяется соответствие территориальному условию специального порядка.</p>')}
function ukrDeceasedNotInherited(){result('yellow','🟡 НАСЛЕДСТВО ЕЩЁ НЕ ОФОРМЛЕНО','<p><b>Смерть собственника подтверждается документом, но наследственные права на автомобиль ещё не оформлены.</b></p><h3>⚖️ Что предусматривает маршрут</h3><p>До оформления наследства при выполнении условий специального порядка рассматривается регистрация автомобиля на российский учёт на ограниченный срок 5 лет.</p><p><b>Выдаётся СТС РФ на ограниченный срок 5 лет без права продажи и с запретом на внесение изменений в регистрационные данные, а также государственные регистрационные номерные знаки РФ.</b></p><p>ПТС на бумажном носителе не выдаётся.</p><h3>📋 Что делать дальше</h3><p>На этом этапе Навигатор рассматривает только возможность регистрации автомобиля на ограниченный срок 5 лет. Вопросы дальнейшего оформления наследственных прав в этой ветке не рассматриваются.</p><h3>🛑 Если возник отказ</h3><p>Устный отказ не является окончательным результатом. Подайте документы официально и получите письменное решение с конкретным правовым основанием. После этого можно определить дальнейший порядок действий и, при наличии оснований, обжалования.</p>')}
function ukrDeceasedInheritance(){q('Оформлено ли наследство на автомобиль?',[['Да — свидетельство о праве на наследство выдано мне',()=>pending('Украина: заявитель является наследником по свидетельству о праве на наследство')],['Да — свидетельство о праве на наследство выдано другому наследнику',ukrDeceasedHeirPresence],['Нет — наследство ещё не оформлено',ukrDeceasedPossessionBasis],['Другая ситуация / нет подходящего варианта',()=>other('У-3.1')]])}
function ukrDeceasedDeathDoc(){q('Имеется ли документ, подтверждающий факт смерти собственника, указанного в украинском свидетельстве о регистрации транспортного средства?',[['Да, имеется',ukrDeceasedInheritance],['Нет',()=>pending('Украина: смерть собственника не подтверждена документально — сначала требуется решить вопрос о документальном подтверждении смерти, после чего определить наследственный маршрут')]],'<p>ℹ️ Документальное подтверждение смерти важно для дальнейшего оформления наследственных прав. Отсутствие такого документа не означает автоматическую невозможность оформления автомобиля, но требует отдельного решения вопроса о подтверждении смерти собственника.</p>')}
function ukrOtherOwnerBasis(){q('На каком основании автомобиль находится в вашем владении?',[['Доверенность',()=>ukrOtherOwnerDocDate('доверенность')],['Договор лизинга',()=>ukrOtherOwnerDocDate('договор лизинга')],['Иной договор',()=>ukrOtherOwnerDocDate('иной договор')],['Дополнительного документа о владении нет',ukrOtherOwnerNoDoc],['Другая ситуация / нет подходящего варианта',()=>other('У-ДР-ВЛ-1')]],'<p>ℹ️ Проект постановления предусматривает документы, подтверждающие полномочия заявителя на владение транспортным средством и (или) представление интересов собственника: доверенность, договор лизинга либо иной договор. При отсутствии таких документов предусматриваются сведения владельца в заявлении об обстоятельствах приобретения транспортного средства (владения транспортным средством).</p>')}
function ukrOtherOwnerIntro(){push();app.innerHTML='<section class="q"><div class="step-marker">УКР-ВЛАДЕЛЕЦ</div><h2>Кто здесь собственник, а кто владелец</h2><p><b>Собственник</b> — лицо, на которое автомобиль зарегистрирован на Украине и которое указано в свидетельстве о регистрации транспортного средства Украины.</p><p><b>Владелец</b> — лицо, которое фактически владеет и пользуется автомобилем, хотя в украинском свидетельстве о регистрации указан другой человек.</p><p>Владение автомобилем может подтверждаться имеющимся <b>свидетельством о регистрации транспортного средства Украины</b>, а также дополнительными документами, подтверждающими полномочия на владение автомобилем или представление интересов собственника: <b>доверенностью, договором лизинга либо иным договором</b>.</p><p>Если таких дополнительных документов нет, проект постановления предусматривает возможность указать в заявлении о регистрационном действии <b>обстоятельства приобретения транспортного средства (владения транспортным средством)</b>.</p><p>ℹ️ В этой ветке наличие украинского свидетельства о регистрации <b>не означает, что заявитель является собственником</b>: в нём указан другой человек. Поэтому Навигатор отдельно проверит основание, на котором автомобиль находится во владении заявителя.</p><div class="opts"><button id="ukr-other-go">Продолжить →</button></div><button class="back" id="back">← Назад</button></section>';document.getElementById('ukr-other-go').onclick=ukrOtherOwnerBasis;document.getElementById('back').onclick=()=>{hist.pop();let f=hist.pop();f&&f()}}
function ukrOwner(){q('Автомобиль находится на украинском регистрационном учёте. На кого он зарегистрирован?',[['На меня',ukrOwnDate],['На другого человека',ukrOtherOwnerIntro],['На умершего собственника',ukrDeceasedDeathDoc],['Другая ситуация / нет подходящего варианта',()=>other('У-1')]],'<p>ℹ️ В этой ветке рассматриваются автомобили, находящиеся на регистрационном учёте Украины и имеющие украинские регистрационные документы.</p>')}
function currentResidence(){q('Где вы проживаете сейчас?',[['На территории одного из новых регионов',registrationStart],['В другом регионе Российской Федерации',registrationStart]],'<p>ℹ️ <b>Ваше нынешнее место проживания само по себе не определяет и не отменяет возможность регистрации автомобиля.</b> Навигатор предназначен в том числе для граждан, которые ранее проживали или были зарегистрированы по месту жительства в новых регионах, но сейчас проживают в других регионах Российской Федерации.</p><p>В следующих шагах Навигатор отдельно проверит обстоятельства, которые имеют юридическое значение: где вы проживали или были зарегистрированы по месту жительства на соответствующую дату, на каком учёте находится автомобиль, на кого он зарегистрирован и какие документы сохранились.</p>')}
function registrationStart(){q('На каком учёте находится автомобиль?',[['ДНР',d1],['ЛНР',lnrD1],['Украина',ukrIntro],['Другая ситуация (например: автомобиль растаможен на Украине, но не зарегистрирован; транзитные номера; снят с регистрационного учёта; документы утрачены и т. д.)',()=>q('Какая именно ситуация?',[['Растаможен на Украине, но не был зарегистрирован',()=>pending('Растаможен на Украине, но не зарегистрирован')],['Транзитные номера Украины',()=>pending('Транзитные номера Украины')],['Снят с регистрационного учёта',()=>pending('Снят с регистрационного учёта')],['Регистрационные документы утрачены',()=>pending('Документы утрачены')],['Автомобиль никогда не был зарегистрирован',()=>pending('Никогда не был зарегистрирован')],['Иностранный учёт другого государства',()=>pending('Иностранный учёт')],['Другая ситуация',()=>other('ДР-1.7')]])]],'Выберите не регион, где автомобиль находится сейчас, а регистрационный учёт по имеющимся документам и государственным номерам.')}
function start(){hist=[];currentResidence()}start();